<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Image Preview</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b0f16;
        --panel: #111827;
        --panel-2: #171f2e;
        --text: #e5e7eb;
        --muted: #94a3b8;
        --border: rgba(148, 163, 184, 0.18);
        --accent: #ef4444;
        --accent-2: #f87171;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        display: grid;
        place-items: center;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(59, 130, 246, 0.14), transparent 30%),
          linear-gradient(180deg, #0b0f16 0%, #070b12 100%);
        color: var(--text);
      }

      main {
        width: min(92vw, 720px);
        padding: 24px;
      }

      .card {
        overflow: hidden;
        border: 1px solid var(--border);
        border-radius: 24px;
        background: linear-gradient(180deg, rgba(17, 24, 39, 0.96), rgba(11, 15, 22, 0.96));
        box-shadow: var(--shadow);
      }

      .preview {
        padding: 24px;
      }

      .image-frame {
        position: relative;
        aspect-ratio: 4 / 3;
        border-radius: 18px;
        overflow: hidden;
        background: linear-gradient(135deg, #1f2937, #0f172a);
        border: 1px solid rgba(255, 255, 255, 0.08);
      }

      .image-frame img {
        width: 100%;
        height: 100%;
        display: block;
        object-fit: cover;
      }

      .meta {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        margin-top: 18px;
      }

      .title {
        margin: 0;
        font-size: 1.1rem;
        font-weight: 600;
      }

      .subtitle {
        margin: 4px 0 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .trigger,
      .secondary {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.2rem;
        font: inherit;
        font-weight: 600;
        cursor: pointer;
        transition: transform 160ms ease, background-color 160ms ease, box-shadow 160ms ease, opacity 160ms ease;
      }

      .trigger {
        background: linear-gradient(180deg, var(--accent), #dc2626);
        color: white;
        box-shadow: 0 12px 30px rgba(239, 68, 68, 0.28);
      }

      .trigger:hover,
      .trigger:focus-visible,
      .secondary:hover,
      .secondary:focus-visible,
      .close:hover,
      .close:focus-visible {
        transform: translateY(-1px);
      }

      .trigger:focus-visible,
      .secondary:focus-visible,
      .close:focus-visible {
        outline: 2px solid rgba(148, 163, 184, 0.8);
        outline-offset: 2px;
      }

      dialog {
        width: min(92vw, 440px);
        border: 1px solid rgba(255, 255, 255, 0.12);
        border-radius: 22px;
        padding: 0;
        background: linear-gradient(180deg, rgba(17, 24, 39, 0.98), rgba(11, 15, 22, 0.98));
        color: var(--text);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgba(2, 6, 23, 0.72);
        backdrop-filter: blur(8px);
      }

      .dialog-shell {
        padding: 24px;
      }

      .dialog-top {
        display: flex;
        gap: 14px;
        align-items: flex-start;
      }

      .icon {
        flex: 0 0 auto;
        width: 44px;
        height: 44px;
        border-radius: 999px;
        display: grid;
        place-items: center;
        background: rgba(239, 68, 68, 0.12);
        color: #fca5a5;
      }

      h2 {
        margin: 0;
        font-size: 1.15rem;
      }

      .dialog-body {
        margin: 10px 0 0;
        color: var(--muted);
        line-height: 1.5;
      }

      .dialog-actions {
        display: flex;
        justify-content: flex-end;
        gap: 12px;
        margin-top: 24px;
      }

      .secondary {
        background: var(--panel-2);
        color: var(--text);
        border: 1px solid var(--border);
      }

      .secondary:hover {
        background: #202a3d;
      }

      .close {
        position: absolute;
        top: 14px;
        right: 14px;
        width: 40px;
        height: 40px;
        border-radius: 999px;
        border: 1px solid var(--border);
        background: rgba(255, 255, 255, 0.03);
        color: var(--text);
        cursor: pointer;
      }

      @media (max-width: 640px) {
        .preview {
          padding: 16px;
        }

        .meta {
          flex-direction: column;
          align-items: stretch;
        }

        .trigger {
          width: 100%;
        }

        .dialog-actions {
          flex-direction: column-reverse;
        }

        .secondary {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <main>
      <section class="card" aria-labelledby="image-title">
        <div class="preview">
          <div class="image-frame">
            <img
              src="https://images.unsplash.com/photo-1516321318423-f06f85e504b3?auto=format&fit=crop&w=1400&q=80"
              alt="Image preview"
            />
          </div>

          <div class="meta">
            <div>
              <h1 class="title" id="image-title">Golden hour portrait</h1>
              <p class="subtitle">Saved to your library</p>
            </div>

            <button class="trigger" type="button" id="open-delete-dialog">
              Delete image
            </button>
          </div>
        </div>
      </section>
    </main>

    <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-description">
      <div class="dialog-shell">
        <button class="close" type="button" aria-label="Close dialog" data-close>&times;</button>

        <div class="dialog-top">
          <div class="icon" aria-hidden="true">
            <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z" />
              <path d="M12 9v4" />
              <path d="M12 17h.01" />
            </svg>
          </div>

          <div>
            <h2 id="delete-title">Delete this image?</h2>
            <p class="dialog-body" id="delete-description">
              This will remove the image from your library. You can’t undo this action.
            </p>
          </div>
        </div>

        <div class="dialog-actions">
          <button class="secondary" type="button" data-close>Cancel</button>
          <button class="trigger" type="button">Delete</button>
        </div>
      </div>
    </dialog>

    <script>
      const dialog = document.getElementById('delete-dialog');
      const openButton = document.getElementById('open-delete-dialog');
      const closeButtons = dialog.querySelectorAll('[data-close]');

      openButton.addEventListener('click', () => {
        dialog.showModal();
      });

      closeButtons.forEach((button) => {
        button.addEventListener('click', () => {
          dialog.close();
        });
      });

      dialog.addEventListener('click', (event) => {
        const rect = dialog.getBoundingClientRect();
        const clickedOutside =
          event.clientX < rect.left ||
          event.clientX > rect.right ||
          event.clientY < rect.top ||
          event.clientY > rect.bottom;

        if (clickedOutside) {
          dialog.close();
        }
      });
    </script>
  </body>
</html>
