        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.2rem;
        font: inherit;
        font-weight: 600;
        cursor: pointer;
        transition: transform 160ms ease, background-color 160ms ease, box-shadow 160ms ease, opacity 160ms ease;
