        outline-offset: 2px;
      }

      dialog {
        width: min(92vw, 440px);
        border: 1px solid rgba(255, 255, 255, 0.12);
        border-radius: 22px;
        padding: 0;
        background: linear-gradient(180deg, rgba(17, 24, 39, 0.98), rgba(11, 15, 22, 0.98));
        color: var(--text);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgba(2, 6, 23, 0.72);
        backdrop-filter: blur(8px);
      }

      .dialog-shell {
        padding: 24px;
